158		uint32_t bits = 0;
159	
160		for (uint32_t irq_type = 0; irq_type < INT_NUMBER_MAX; irq_type++) {
161			if (irq_type == 32) {
162				BK_LOGD("int", "bits=%x\r\n", bits);
163				bits = 0;
164			}
165	
166			if (NVIC_GetTargetState(irq_type)) {
167				uint32_t bit = irq_type % 32;
168				bits |= BIT(bit);
169			}
170		}
171	
172		BK_LOGD("int", "high bits=%x\r\n", bits);
173	}
174	
175	void arch_int_set_target_state_all(void)
176	{
177		dump_state();
178		for (uint32_t irq_type = 0; irq_type < INT_NUMBER_MAX; irq_type++) {
179			NVIC_SetTargetState(irq_type);
180		}
181		dump_state();
182	}
