184	void arch_int_dump_statis(void)
185	{
186	#if CONFIG_ARCH_INT_STATIS
187		for (uint32_t irq_type = 0; irq_type < INT_NUMBER_MAX; irq_type++) {
188			BK_LOGD(TAG, "[%d] = %u\r\n", irq_type, s_int_statis[irq_type]);
189		}
190	#endif
