115	/* Timer adapter - bridges Beken timer to NuttX watchdog */
116	
117	struct timer_adpt
118	{
119	  struct wdog_s wdog;       /* NuttX watchdog handle */
120	  bool          repeat;     /* True if periodic timer */
121	  uint32_t      delay;      /* Timeout in ticks */
122	  void          *priv;      /* Pointer back to beken_timer_t / beken2_timer_t */
123	};
124	
125	/* Message queue adapter */
126	
127	struct mq_adpt_s
128	{
129	  struct file mq;           /* NuttX message queue handle */
130	  uint32_t    msgsize;      /* Message size in bytes */
131	  char        name[16];     /* Message queue name */
132	  char        cname[32];    /* Display name for debug */
133	};
