138	
139	static inline bk_err_t beken_errno_trans(int ret)
140	{
141	  if (!ret)
142	    {
143	      return BK_OK;
144	    }
145	
146	  return BK_FAIL;
147	}
148	
149	static void os_timer_callback(wdparm_t arg)
150	{
151	  struct timer_adpt *timer_apt = (struct timer_adpt *)arg;
152	
153	  if (timer_apt->repeat)
154	    {
155	      beken_timer_t *timer = (beken_timer_t *)timer_apt->priv;
156	      if (timer->function)
157	        {
158	          timer->function(timer->arg);
159	        }
160	
161	      wd_start(&timer_apt->wdog, timer_apt->delay,
162	               os_timer_callback, arg);
163	    }
164	  else
165	    {
166	      beken2_timer_t *timer = (beken2_timer_t *)timer_apt->priv;
167	      if (timer->function)
168	        {
169	          timer->function(timer->left_arg, timer->right_arg);
170	        }
171	    }
172	}
