472	                            uint32_t timeout_ms)
473	{
474	  int ret;
475	  sem_t *sem = (sem_t *)(*semaphore);
476	
477	  if (timeout_ms == 0)
478	    {
479	      ret = nxsem_trywait(sem);
480	    }
481	  else if (timeout_ms == BEKEN_WAIT_FOREVER)
482	    {
483	      ret = nxsem_wait(sem);
484	    }
485	  else
486	    {
487	      ret = nxsem_tickwait(sem, MSEC2TICK(timeout_ms));
488	    }
489	
490	  if (ret != OK)
491	    {
492	      wlerr("ERROR: Failed to get semaphore:%d\n", ret);
493	    }
494	
495	  return beken_errno_trans(ret);
496	}
