642	bk_err_t rtos_init_queue(beken_queue_t *queue, const char *name,
643	                         uint32_t message_size,
644	                         uint32_t number_of_messages)
645	{
646	  struct mq_attr attr;
647	  struct mq_adpt_s *mq_adpt;
648	  int ret;
649	
650	  mq_adpt = kmm_malloc(sizeof(struct mq_adpt_s));
651	  if (!mq_adpt)
652	    {
653	      wlerr("ERROR: Failed to kmm_malloc\n");
654	      return BK_FAIL;
655	    }
656	
657	  memset(mq_adpt, 0x0, sizeof(struct mq_adpt_s));
658	
659	  if (name)
660	    {
661	      snprintf(mq_adpt->name, sizeof(mq_adpt->name), "/tmp/%s", name);
662	    }
663	  else
664	    {
665	      snprintf(mq_adpt->name, sizeof(mq_adpt->name), "/tmp/%p",
666	               mq_adpt);
667	    }
668	
669	  attr.mq_maxmsg  = number_of_messages;
670	  attr.mq_msgsize = message_size;
671	  attr.mq_curmsgs = 0;
672	  attr.mq_flags   = 0;
673	
674	  strncpy(mq_adpt->cname, name ? name : "null",
675	          sizeof(mq_adpt->cname) - 1);
676	
677	  ret = file_mq_open(&mq_adpt->mq, mq_adpt->name,
678	                     O_RDWR | O_CREAT, 0644, &attr);
679	  if (ret < 0)
680	    {
681	      wlerr("ERROR: Failed to create mqueue\n");
682	      kmm_free(mq_adpt);
683	      return beken_errno_trans(ret);
684	    }
685	
686	  mq_adpt->msgsize = message_size;
687	  *queue           = mq_adpt;
688	
689	  return beken_errno_trans(ret);
690	}
691	
692	bk_err_t rtos_push_to_queue(beken_queue_t *queue, void *message,
693	                            uint32_t timeout_ms)
694	{
695	  int ret;
696	  struct mq_adpt_s *mq_adpt = (struct mq_adpt_s *)*queue;
697	
698	  if (timeout_ms == BEKEN_WAIT_FOREVER || timeout_ms == 0)
699	    {
700	      ret = file_mq_send(&mq_adpt->mq, (const char *)message,
701	                         mq_adpt->msgsize, 0);
702	      if (ret < 0)
703	        {
704	          wlerr("Failed to send message to mqueue error=%d\n", ret);
705	        }
706	    }
707	  else
708	    {
709	      struct timespec timeout;
710	
711	      clock_gettime(CLOCK_REALTIME, &timeout);
712	      timeout.tv_sec  += timeout_ms / 1000;
713	      timeout.tv_nsec += (timeout_ms % 1000) * 1000 * 1000;
714	
715	      if (timeout.tv_nsec >= 1000000000)
716	        {
717	          timeout.tv_sec  += timeout.tv_nsec / 1000000000;
718	          timeout.tv_nsec %= 1000000000;
719	        }
720	
721	      ret = file_mq_timedsend(&mq_adpt->mq, (const char *)message,
722	                              mq_adpt->msgsize, 0, &timeout);
723	      if (ret < 0)
724	        {
725	          wlerr("Failed to timedsend message to mqueue error=%d\n", ret);
726	        }
727	    }
728	
729	  return beken_errno_trans(ret);
730	}
731	
732	bk_err_t rtos_push_to_queue_front(beken_queue_t *queue, void *message,
733	                                  uint32_t timeout_ms)
734	{
735	  /* NuttX mq does not support front insertion; fall back to normal send */
736	
737	  return rtos_push_to_queue(queue, message, timeout_ms);
738	}
739	
740	bk_err_t rtos_pop_from_queue(beken_queue_t *queue, void *message,
741	                             uint32_t timeout_ms)
742	{
743	  int ret;
744	  struct mq_adpt_s *mq_adpt = (struct mq_adpt_s *)*queue;
745	
746	  if (timeout_ms == BEKEN_WAIT_FOREVER)
747	    {
748	      ret = file_mq_receive(&mq_adpt->mq, message,
749	                            mq_adpt->msgsize, 0);
750	      if (ret < 0)
751	        {
752	          wlerr("Failed to receive message from mqueue error=%d\n", ret);
753	        }
754	    }
755	  else
756	    {
757	      struct timespec timeout;
758	
759	      clock_gettime(CLOCK_REALTIME, &timeout);
760	      timeout.tv_sec  += timeout_ms / 1000;
761	      timeout.tv_nsec += (timeout_ms % 1000) * 1000 * 1000;
762	
763	      if (timeout.tv_nsec >= 1000000000)
764	        {
765	          timeout.tv_sec  += timeout.tv_nsec / 1000000000;
766	          timeout.tv_nsec %= 1000000000;
767	        }
768	
769	      ret = file_mq_timedreceive(&mq_adpt->mq, message,
770	                                 mq_adpt->msgsize, 0, &timeout);
771	      if (ret < 0)
772	        {
773	          wlerr("Failed to timedreceive message from mqueue error=%d\n",
774	                ret);
775	        }
776	    }
777	
778	  return ret > 0 ? BK_OK : BK_FAIL;
779	}
