839	beken_event_flags_t rtos_wait_for_event_flags(
840	    beken_event_t *event_flags,
841	    uint32_t flags_to_wait_for,
842	    beken_bool_t clear_set_flags,
843	    beken_event_flags_wait_option_t wait_option,
844	    uint32_t timeout_ms)
845	{
846	  sem_t *sem = (sem_t *)(*event_flags);
