1571	bk_err_t rtos_init_event_ex(rtos_event_ext_t *event)
1572	{
1573	  sem_t *sem;
1574	
1575	  sem = kmm_malloc(sizeof(sem_t));
1576	  if (!sem)
1577	    {
1578	      return BK_FAIL;
1579	    }
1580	
1581	  nxsem_init(sem, 0, 0);
1582	  event->event_semaphore = sem;
1583	  event->event_flag = 0;
1584	
1585	  return BK_OK;
1586	}
1587	
1588	bk_err_t rtos_deinit_event_ex(rtos_event_ext_t *event)
1589	{
1590	  sem_t *sem = (sem_t *)event->event_semaphore;
1591	
1592	  nxsem_destroy(sem);
1593	  kmm_free(sem);
1594	
1595	  return BK_OK;
1596	}
1597	
1598	bk_err_t rtos_set_event_ex(rtos_event_ext_t *event, u32 event_flag)
1599	{
1600	  sem_t *sem = (sem_t *)event->event_semaphore;
1601	
1602	  event->event_flag |= event_flag;
1603	  nxsem_post(sem);
1604	
1605	  return BK_OK;
1606	}
1607	
1608	u32 rtos_wait_event_ex(rtos_event_ext_t *event, u32 event_flag,
1609	                       u32 any_event, u32 timeout)
1610	{
1611	  sem_t *sem = (sem_t *)event->event_semaphore;
1612	  int ret;
1613	
1614	  if (timeout == BEKEN_WAIT_FOREVER)
1615	    {
1616	      ret = nxsem_wait(sem);
1617	    }
1618	  else if (timeout == 0)
1619	    {
1620	      ret = nxsem_trywait(sem);
1621	    }
1622	  else
1623	    {
1624	      ret = nxsem_tickwait(sem, MSEC2TICK(timeout));
1625	    }
1626	
1627	  if (ret == OK)
1628	    {
1629	      u32 flags = event->event_flag & event_flag;
1630	      event->event_flag &= ~event_flag;
1631	      return flags;
1632	    }
1633	
1634	  return 0;
1635	}
