126	 * Name: up_irqinitialize
127	 *
128	 * Description:
129	 *   Bring the NVIC up to a known, ready state.  Called from up_initialize().
130	 *
131	 ****************************************************************************/
132	
133	void up_irqinitialize(void)
134	{
135	  uint32_t regaddr;
136	  int num_priority_registers;
137	  int i;
138	
139	  /* Disable all external interrupts. */
140	
141	  for (i = 0; i < NR_IRQS - BK7258_IRQ_FIRST; i += 32)
142	    {
143	      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
144	    }
145	
146	  /* Point VTOR at our flash-resident vector table (also set in __start;
147	   * redundant here but deterministic).
148	   */
149	
150	  putreg32((uint32_t)_vectors, NVIC_VECTAB);
151	
152	#ifdef CONFIG_ARCH_RAMVECTORS
153	  arm_ramvec_initialize();
154	#endif
155	
156	  /* Default-prioritise the system exceptions. */
157	
158	  putreg32(DEFPRIORITY32, NVIC_SYSH4_7_PRIORITY);
159	  putreg32(DEFPRIORITY32, NVIC_SYSH8_11_PRIORITY);
160	  putreg32(DEFPRIORITY32, NVIC_SYSH12_15_PRIORITY);
161	
162	  /* The NVIC ICTR register (bits 0-4) holds (number of IRQ lines / 32) - 1,
163	   * which also tells us how many priority registers to default-fill.
164	   */
165	
166	  num_priority_registers = (getreg32(NVIC_ICTR) + 1) * 8;
167	
168	  regaddr = NVIC_IRQ0_3_PRIORITY;
169	  while (num_priority_registers--)
170	    {
171	      putreg32(DEFPRIORITY32, regaddr);
172	      regaddr += 4;
173	    }
174	
175	  /* Attach the SVCall and HardFault handlers used by the scheduler. */
176	
177	  irq_attach(NVIC_IRQ_SVCALL, arm_svcall, NULL);
178	  irq_attach(NVIC_IRQ_HARDFAULT, arm_hardfault, NULL);
179	
180	  /* PendSV runs at the lowest priority so it never preempts device IRQs. */
181	
182	  up_prioritize_irq(NVIC_IRQ_PENDSV, NVIC_SYSH_PRIORITY_MIN);
183	  bk7258_prioritize_syscall(NVIC_SYSH_SVCALL_PRIORITY);
184	
185	  /* Enable the MemManage fault if the MPU is in use. */
186	
187	#ifdef CONFIG_ARM_MPU
188	  irq_attach(NVIC_IRQ_MEMFAULT, arm_memfault, NULL);
189	  up_enable_irq(NVIC_IRQ_MEMFAULT);
190	#endif
191	
192	#ifndef CONFIG_SUPPRESS_INTERRUPTS
193	
194	  /* Colour the interrupt stack (writes a sentinel pattern) and unmask IRQs. */
195	
196	  arm_color_intstack();
197	  up_irq_enable();
198	#endif
199	}
200	
201	/****************************************************************************
202	 * Name: bk7258_irqinfo
203	 *
204	 * Description:
205	 *   Map a NuttX IRQ number to the (register, bit) pair that enables/disables
206	 *   it in the NVIC, honouring the enable/clear bank offset for external IRQs
207	 *   and the SYSHCON/SYSTICK control bits for the handful of manageable
208	 *   system exceptions.
209	 *
210	 ****************************************************************************/
211	
212	static int bk7258_irqinfo(int irq, uintptr_t *regaddr, uint32_t *bit,
213	                          uintptr_t offset)
214	{
215	  int n;
216	
217	  DEBUGASSERT(irq >= NVIC_IRQ_NMI && irq < NR_IRQS);
218	
219	  /* External device interrupt? */
220	
221	  if (irq >= BK7258_IRQ_FIRST)
222	    {
223	      n        = irq - BK7258_IRQ_FIRST;
224	      *regaddr = NVIC_IRQ_ENABLE(n) + offset;
225	      *bit     = (uint32_t)0x1 << (n & 0x1f);
226	    }
227	
228	  /* Processor exception -- only a few can be enabled/disabled. */
229	
230	  else
231	    {
232	      *regaddr = NVIC_SYSHCON;
233	      if (irq == NVIC_IRQ_MEMFAULT)
234	        {
235	          *bit = NVIC_SYSHCON_MEMFAULTENA;
236	        }
237	      else if (irq == NVIC_IRQ_BUSFAULT)
238	        {
239	          *bit = NVIC_SYSHCON_BUSFAULTENA;
240	        }
241	      else if (irq == NVIC_IRQ_USAGEFAULT)
242	        {
243	          *bit = NVIC_SYSHCON_USGFAULTENA;
244	        }
245	      else if (irq == NVIC_IRQ_SYSTICK)
246	        {
247	          *regaddr = NVIC_SYSTICK_CTRL;
248	          *bit = NVIC_SYSTICK_CTRL_ENABLE;
249	        }
250	      else
251	        {
252	          return -EINVAL;  /* Invalid or unsupported exception */
253	        }
254	    }
255	
256	  return OK;
257	}
258	
259	/****************************************************************************
260	 * Name: up_disable_irq
261	 *
262	 ****************************************************************************/
263	
264	void up_disable_irq(int irq)
265	{
266	  uintptr_t regaddr;
267	  uint32_t  regval;
268	  uint32_t  bit;
269	
270	  if (bk7258_irqinfo(irq, &regaddr, &bit, NVIC_CLRENA_OFFSET) == 0)
271	    {
272	      if (irq >= BK7258_IRQ_FIRST)
273	        {
274	          /* External: write 1 to the Clear-Enable bank bit. */
275	
276	          putreg32(bit, regaddr);
277	        }
278	      else
279	        {
280	          /* System exception: clear the SYSHCON / SYSTICK bit. */
281	
282	          regval  = getreg32(regaddr);
283	          regval &= ~bit;
284	          putreg32(regval, regaddr);
285	        }
286	    }
287	}
288	
289	/****************************************************************************
290	 * Name: up_enable_irq
291	 *
292	 ****************************************************************************/
293	
294	void up_enable_irq(int irq)
295	{
296	  uintptr_t regaddr;
297	  uint32_t  regval;
298	  uint32_t  bit;
299	
300	  if (bk7258_irqinfo(irq, &regaddr, &bit, NVIC_ENA_OFFSET) == 0)
301	    {
302	      if (irq >= BK7258_IRQ_FIRST)
303	        {
304	          /* External: write 1 to the Set-Enable bank bit. */
305	
306	          putreg32(bit, regaddr);
307	        }
308	      else
309	        {
310	          /* System exception: set the SYSHCON / SYSTICK bit. */
311	
312	          regval  = getreg32(regaddr);
313	          regval |= bit;
314	          putreg32(regval, regaddr);
315	        }
316	    }
317	}
318	
319	/****************************************************************************
320	 * Name: arm_ack_irq
321	 *
322	 * Description:
323	 *   Acknowledge an IRQ.  Cortex-M NVIC IRQs are auto-acknowledged on
324	 *   exception entry, so there is nothing to do here (the stub is required
325	 *   by arm_doirq.c).
326	 *
327	 ****************************************************************************/
328	
329	void arm_ack_irq(int irq)
330	{
331	}
