226	void group_isr(uint32_t group_id, uint32_t int_status)
227	{
228		uint32_t int_num;
229		isr_t *cur_ptr;
230		uint32_t status;
231		LIST_HEADER_T *next;
232		LIST_HEADER_T *pos;
233	
234		status = int_status & s_isr_mask[group_id];
235		// ICU_LOGV("group_isr:%x:%x\r\n", int_status, status);
236	
237		if (s_int_mac_ps_callback) {
238			s_int_mac_ps_callback(status);
239		}
240	
241		list_for_each_safe(pos, next, &s_int_lists[group_id].isr) {
242			cur_ptr= list_entry(pos, isr_t, list);
243			int_num = cur_ptr->int_num;
244	
245			if ((BIT(int_num) & status)) {
246				cur_ptr->isr_func();
247				status &= ~(BIT(int_num));
248	#if CONFIG_INT_STATIS
249		if(group_id == 1)
250			g_int_statis_num.fiq_int_statis[int_num-FIQ_START_COUNT_BIT] ++;
251		else
252			g_int_statis_num.irq_int_statis[int_num] ++;
253	#endif
254			}
255	
256			if (0 == status)
257				return;
258		}
259	}
