72	bk_err_t amp_res_acquire_cnt(u16 res_id, u16 cpu_id, amp_res_req_cnt_t *cnt_list)
73	{
74		if(res_id >= AMP_RES_ID_MAX)
75			return BK_ERR_PARAM;
76	
77		if(amp_res_sync[res_id].inited == 0)
78			return BK_ERR_NOT_INIT;
79	
80		if(cpu_id >= AMP_CPU_CNT)
81			return BK_ERR_PARAM;
82	
83		u16		i = 0;
84		u16 	all_cnt = 0;
85		
86		u32  int_mask = amp_enter_critical();
87	
88		for(i = 0; i < AMP_CPU_CNT; i++)
89		{
90			all_cnt += amp_res_sync[res_id].req_cnt[i];
91		}
92	
93		cnt_list->self_req_cnt = amp_res_sync[res_id].req_cnt[cpu_id];
94		cnt_list->others_req_cnt = all_cnt - cnt_list->self_req_cnt;
95	
96		amp_res_sync[res_id].req_cnt[cpu_id]++;
97	
98		amp_exit_critical(int_mask);
99	
100		return BK_OK;
101		
102	}
