106		if(res_id >= AMP_RES_ID_MAX)
107			return BK_ERR_PARAM;
108	
109		if(amp_res_sync[res_id].inited == 0)
110			return BK_ERR_NOT_INIT;
111	
112		if(cpu_id >= AMP_CPU_CNT)
113			return BK_ERR_PARAM;
114	
115		u16		i = 0;
116		
117		bk_err_t	ret_val = BK_FAIL;
118	
119		u32  int_mask = amp_enter_critical();
120	
121		if(amp_res_sync[res_id].req_cnt[cpu_id] > 0)
122		{
123			amp_res_sync[res_id].req_cnt[cpu_id]--;
124	
125			u16 	all_cnt = 0;
126	
127			for(i = 0; i < AMP_CPU_CNT; i++)
128			{
129				all_cnt += amp_res_sync[res_id].req_cnt[i];
130			}
131	
132			cnt_list->self_req_cnt = amp_res_sync[res_id].req_cnt[cpu_id];
133			cnt_list->others_req_cnt = all_cnt - cnt_list->self_req_cnt;
134	
135			ret_val = BK_OK;
136		}
137	
138		amp_exit_critical(int_mask);
139	
140		return ret_val;
