142	int mbox0_drv_init(void)
143	{
144		if(mbox0_init == 1)
145			return 0;
146	
147		mbox0_dev.chn_drv[0] = &hal_chn0_drv;
148		mbox0_dev.chn_drv[1] = &hal_chn1_drv;
149		mbox0_dev.chn_drv[2] = &hal_chn2_drv;
150	
151		mbox0_dev.rx_callback = NULL;
152	
153		mbox0_hal_init(&mbox0_dev.hal);
154	
155		int int_src = INT_SRC_MAILBOX;
156	
157		bk_int_isr_register(int_src, mbox0_drv_isr_handler, NULL);
