170	
171	int mbox0_drv_deinit(void)
172	{
173		if(mbox0_init == 0)
174			return 0;
175	
176		uint8_t int_src = INT_SRC_MAILBOX;
177	
178		// sys_drv_int_group2_disable(1 << (int_src - 32));
179	
180	#if CONFIG_SOC_SMP
181		/* disable system interrupt, every channel is hard-bound to a processor */
182		sys_drv_core_intr_group2_disable(CPU0_CORE_ID, (1 << (int_src - 32)));
183		
184		/* disable system interrupt, every channel is hard-bound to a processor */
185		sys_drv_core_intr_group2_disable(CPU1_CORE_ID, (1 << (int_src - 32)));
186	
187		mbox0_dev.chn_drv[CPU0_CORE_ID]->chn_int_enable(&mbox0_dev.hal, 0);
188		mbox0_dev.chn_drv[CPU1_CORE_ID]->chn_int_enable(&mbox0_dev.hal, 0);
189	#else
190		sys_drv_int_group2_disable(1 << (int_src - 32));
191		mbox0_dev.chn_drv[SELF_CHNL]->chn_int_enable(&mbox0_dev.hal, 0);
192	#endif
193	
194		bk_int_isr_unregister(int_src);
195	
196	#if CONFIG_SOC_SMP
197		mbox0_hal_dev_deinit(&mbox0_dev.hal);  /* can only be de-initialized by CPU0. */
198	#else
199		if(SELF_CHNL == 0)
200			mbox0_hal_dev_deinit(&mbox0_dev.hal);  /* can only be de-initialized by CPU0. */
201	#endif
202	
203		mbox0_hal_deinit(&mbox0_dev.hal);
204		
205		mbox0_dev.rx_callback = NULL;
206	
207		mbox0_init = 0;
208	
209		return 0;
210	}
