1	/****************************************************************************
2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/bk7258_irq.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * Beken BK7258 (T5-AI, Cortex-M33) NVIC interrupt support for NuttX N2.
7	 *
8	 * Standard Cortex-M NVIC glue, modelled on nuttx/arch/arm/src/mps/mps_irq.c.
9	 * Provides up_irqinitialize() / up_enable_irq() / up_disable_irq() /
10	 * up_prioritize_irq() / arm_ack_irq() that the common armv8-m dispatch
11	 * code (arm_doirq.c, arm_exception.S) expects.  The BK7258 exposes 48
12	 * external IRQs (NR_IRQS=48 -> vector slots [16..63]); the chip-provided
13	 * vector table (bk7258_vectors.c) routes SysTick + all external IRQs to
14	 * exception_direct and the system exceptions to exception_common, so once
15	 * up_irqinitialize() runs, irq_attach()/irq_dispatch() work normally.
16	 *
17	 * System-exception IRQ numbers use the canonical arm_m names from nvic.h
18	 * (NVIC_IRQ_HARDFAULT, NVIC_IRQ_SVCALL, NVIC_IRQ_PENDSV, ...) which equal
19	 * the BK7258_IRQ_* values in chip/include/irq.h.
20	 ****************************************************************************/
21	
22	/****************************************************************************
23	 * Included Files
24	 ****************************************************************************/
25	
26	#include <nuttx/config.h>
27	
28	#include <stdint.h>
29	#include <assert.h>
30	#include <debug.h>
31	
32	#include <nuttx/arch.h>
33	#include <arch/irq.h>
