259	/****************************************************************************
260	 * Name: up_disable_irq
261	 *
262	 ****************************************************************************/
263	
264	void up_disable_irq(int irq)
265	{
266	  uintptr_t regaddr;
267	  uint32_t  regval;
268	  uint32_t  bit;
269	
270	  if (bk7258_irqinfo(irq, &regaddr, &bit, NVIC_CLRENA_OFFSET) == 0)
271	    {
272	      if (irq >= BK7258_IRQ_FIRST)
273	        {
274	          /* External: write 1 to the Clear-Enable bank bit. */
275	
276	          putreg32(bit, regaddr);
277	        }
278	      else
279	        {
280	          /* System exception: clear the SYSHCON / SYSTICK bit. */
281	
282	          regval  = getreg32(regaddr);
283	          regval &= ~bit;
284	          putreg32(regval, regaddr);
285	        }
286	    }
287	}
